// it is required to disable interrupts prior to EEPROM access!
void disableAllInterrupts()
{

  timerDetachInterrupt(variableTimer);
  timerDetachInterrupt(fixedTimer);

  Serial.print("Interrupts disabled, reboot required!\n");
