void Dashboard::drawFrame()
{
    // speed
    drawArc(SPEED_CIRCLE_CENTER_X, SPEED_CIRCLE_CENTER_Y, SPEED_CIRCLE_RADIUS,
            SPEED_CIRCLE_ANGLE_START, SPEED_CIRCLE_ANGLE_END, TFT_LIGHTGREY);
