    str[0] = gear;

    _tft.setTextColor(TFT_BLACK);
    _tft.drawCentreString(String((lastVal)), RPM_CIRCLE_CENTER_X, RPM_CIRCLE_CENTER_Y - 7, 2);

    _tft.setTextColor(TFT_WHITE);
