#define SCREEN_WIDTH 160
#define SCREEN_HEIGHT 80
#define DEG2RAD 0.0174532925
#define SPEED_MIN 0
#define SPEED_MAX 120
#define RPM_MIN 0
#define RPM_MAX 500
#define FUEL_MIN 0
#define FUEL_MAX 100
